def flood_fill_outside(g, bg):
    h,w=len(g),len(g[0])
    out=[[c for c in r] for r in g]
    from collections import deque
    seen=set()
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg and (i,j) not in seen: q.append((i,j)); seen.add((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg and (i,j) not in seen: q.append((i,j)); seen.add((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==bg and (ni,nj) not in seen:
                seen.add((ni,nj)); q.append((ni,nj))
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and (i,j) not in seen:
                out[i][j]=4
    return out

def transform(grid):
    from collections import Counter
    c=Counter(x for r in grid for x in r)
    bg=c.most_common(1)[0][0]
    return flood_fill_outside(grid, bg)

